export const removeRecursive = (fileSystem, path) => {
    if (!fileSystem.existsSync(path))
        return;
    for (const entry of fileSystem.readdirSync(path)) {
        const entryPath = `${path.endsWith('/') ? path : `${path}/`}${entry}`;
        if (fileSystem.statSync(entryPath).isDirectory())
            removeRecursive(fileSystem, entryPath);
        else
            fileSystem.unlinkSync(entryPath);
    }
    fileSystem.rmdirSync(path);
};
export const readJsonFile = (fileSystem, path, fallback = null) => {
    try {
        if (fileSystem.existsSync(path)) {
            return JSON.parse(fileSystem.readFileSync(path, 'utf-8'));
        }
    }
    catch (err) {
        console.error(`readJsonFile(${path}):`, err);
    }
    return fallback;
};
export const writeJsonFile = (fileSystem, path, data, mkdirParent = false) => {
    if (mkdirParent) {
        const dir = path.slice(0, path.lastIndexOf('/')) || '/';
        ensureDir(fileSystem, dir);
    }
    fileSystem.writeFileSync(path, JSON.stringify(data, null, 2));
};
export const ensureDir = (fileSystem, path) => {
    if (!fileSystem.existsSync(path)) {
        fileSystem.mkdirSync(path, { recursive: true });
    }
};
