import { Platform } from '@shared/index';
import React from 'react';
const platform = Platform.getInstance();
export const ContextMenu = ({ componentRef }) => {
    const id = 'context-menu-' + Math.random().toString(36).substring(2, 9);
    const [items, setItems] = React.useState([
    //     {id: '0', type:'action', title: 'Edit'},
    //     {id: '1', type:'action', title: 'Open'},
    //     {id: '2', type:'action', title: 'Delete'},
    ]);
    const onClickRef = React.useRef(null);
    const [customModule, setCustomModule] = React.useState(null);
    const ComponentTemplateRef = React.useRef(({ item, onClick }) => {
        return React.createElement("button", { className: 'action-default-btn', key: item.id, onClick: ev => onClick(ev) }, item.title);
    });
    React.useEffect(() => {
        componentRef({ setItems, setOnClick: callback => onClickRef.current = callback });
        const fs = platform.host.getFS();
        const templateFilePath = '/usr/lib/ui/menuItem.js';
        const fileExist = fs.existsSync(templateFilePath);
        if (fileExist) {
            const fileContent = fs.readFileSync(templateFilePath);
            const mod = platform.host.execString(fileContent.toString(), templateFilePath);
            setCustomModule(mod);
            ComponentTemplateRef.current = mod.default || ComponentTemplateRef.current;
            // setCustomStyles(mod?.getStyles?.(id, items) || "")
        }
    }, [items]);
    return (React.createElement("div", { id: id },
        React.createElement("style", { dangerouslySetInnerHTML: { __html: `
                #${id} { 
                    display: flex;
                    flex-direction: column;

                    gap: 1px;
                    // background-color: rgba(230, 230, 230, 0.5);
                    // box-shadow: rgba(0, 0, 0, 0.16) 0px 1px 4px;

                }

                #${id} > button.action-default-btn {
                    cursor: pointer;
                    text-align: start;

                    width: 15rem;
                    height: 3rem;
                    border: none;

                    background: transparent;
                }

                #${id} > button.action-default-btn:hover {
                    background: black;
                    color: white;
                    // border-radius: 12px;
                }
                
                ${customModule ? customModule.getStyles(id, items) : ''}
            ` } }),
        items.map(item => React.createElement(ComponentTemplateRef.current, { key: item.id, item: item, onClick: () => onClickRef.current ? onClickRef.current(item) : null }))));
};
